BEGIN;
CREATE TABLE "shopper_accounts" ("id" TEXT NOT NULL, "customerId" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "shopper_accounts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "shopper_accounts_customerId_key" ON "shopper_accounts"("customerId");
ALTER TABLE "shopper_accounts" ADD CONSTRAINT "shopper_accounts_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "customers"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "shopper_sessions" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "customerId" TEXT, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "shopper_sessions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "shopper_sessions_tokenHash_key" ON "shopper_sessions"("tokenHash");
CREATE INDEX "shopper_sessions_customerId_expiresAt_idx" ON "shopper_sessions"("customerId", "expiresAt");
ALTER TABLE "shopper_sessions" ADD CONSTRAINT "shopper_sessions_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "customers"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "shopper_order_access" ("id" TEXT NOT NULL, "sessionId" TEXT NOT NULL, "orderId" TEXT NOT NULL, CONSTRAINT "shopper_order_access_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "shopper_order_access_orderId_key" ON "shopper_order_access"("orderId");
CREATE INDEX "shopper_order_access_sessionId_idx" ON "shopper_order_access"("sessionId");
ALTER TABLE "shopper_order_access" ADD CONSTRAINT "shopper_order_access_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "shopper_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "shopper_order_access" ADD CONSTRAINT "shopper_order_access_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "orders"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "newsletter_subscriptions" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "subscribedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "unsubscribedAt" TIMESTAMP(3), CONSTRAINT "newsletter_subscriptions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "newsletter_subscriptions_email_key" ON "newsletter_subscriptions"("email");
CREATE UNIQUE INDEX "newsletter_subscriptions_tokenHash_key" ON "newsletter_subscriptions"("tokenHash");
CREATE TABLE "storefront_throttles" ("key" TEXT NOT NULL, "count" INTEGER NOT NULL DEFAULT 0, "expiresAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "storefront_throttles_pkey" PRIMARY KEY ("key"));
CREATE INDEX "storefront_throttles_expiresAt_idx" ON "storefront_throttles"("expiresAt");
COMMIT;
